class JSON(Content):
    def __init__(self, data: typing.Any) -> None:
        self._data = data

    def encode(self) -> Stream:
        content = json.dumps(
            self._data,
            ensure_ascii=False,
            separators=(",", ":"),
            allow_nan=False
        ).encode("utf-8")
        return ByteStream(content)

    def content_type(self) -> str:
        return "application/json"

    def __repr__(self) -> str:
        return f"<JSON {self._data!r}>"

