def is_idle(self) -> bool:
    return (
        self.send_state == State.SEND_METHOD_LINE or
        self.recv_state == State.RECV_METHOD_LINE
    )

def description(self) -> str:
    return {
        State.SEND_METHOD_LINE: "idle",
        State.CLOSED: "closed",
    }.get(self.send_state, "active")

