def encode_host(host: str) -> str:
    if not host:
        return ""

    elif IPv4_STYLE_HOSTNAME.match(host):
        # Validate IPv4 hostnames like #.#.#.#
        #
        # From https://datatracker.ietf.org/doc/html/rfc3986/#section-3.2.2
        #
        # IPv4address = dec-octet "." dec-octet "." dec-octet "." dec-octet
        try:
            ipaddress.IPv4Address(host)
        except ipaddress.AddressValueError:
            raise InvalidURL(f"Invalid IPv4 address: {host!r}")
        return host

    elif IPv6_STYLE_HOSTNAME.match(host):
        # Validate IPv6 hostnames like [...]
        #
        # From https://datatracker.ietf.org/doc/html/rfc3986/#section-3.2.2
        #
        # "A host identified by an Internet Protocol literal address, version 6
        # [RFC3513] or later, is distinguished by enclosing the IP literal
        # within square brackets ("[" and "]").  This is the only place where
        # square bracket characters are allowed in the URI syntax."
        try:
            ipaddress.IPv6Address(host[1:-1])
        except ipaddress.AddressValueError:
            raise InvalidURL(f"Invalid IPv6 address: {host!r}")
        return host[1:-1]

    elif not host.isascii():
        try:
            import idna  # type: ignore
        except ImportError:
            raise InvalidURL(
                f"Cannot handle URL with IDNA hostname: {host!r}. "
                f"Package 'idna' is not installed."
            )

        # IDNA hostnames
        try:
            return idna.encode(host.lower()).decode("ascii")
        except idna.IDNAError:
            raise InvalidURL(f"Invalid IDNA hostname: {host!r}")

    # Regular ASCII hostnames
    #
    # From https://datatracker.ietf.org/doc/html/rfc3986/#section-3.2.2
    #
    # reg-name    = *( unreserved / pct-encoded / sub-delims )
    WHATWG_SAFE = '"`{}%|\\'
    return quote(host.lower(), safe=SUB_DELIMS + WHATWG_SAFE)

def validate_path(path: str, has_scheme: bool, has_authority: bool) -> None:
    """
    Path validation rules that depend on if the URL contains
    a scheme or authority component.

    See https://datatracker.ietf.org/doc/html/rfc3986.html#section-3.3
    """
    if has_authority:
        # If a URI contains an authority component, then the path component
        # must either be empty or begin with a slash ("/") character."
        if path and not path.startswith("/"):
            raise InvalidURL("For absolute URLs, path must be empty or begin with '/'")

    if not has_scheme and not has_authority:
        # If a URI does not contain an authority component, then the path cannot begin
        # with two slash characters ("//").
        if path.startswith("//"):
            raise InvalidURL("Relative URLs cannot have a path starting with '//'")

        # In addition, a URI reference (Section 4.1) may be a relative-path reference,
        # in which case the first path segment cannot contain a colon (":") character.
        if path.startswith(":"):
            raise InvalidURL("Relative URLs cannot have a path starting with ':'")

def normalize_path(path: str) -> str:
    """
    Drop "." and ".." segments from a URL path.

    For example:

        normalize_path("/path/./to/somewhere/..") == "/path/to"
    """
    # Fast return when no '.' characters in the path.
    if "." not in path:
        return path

    components = path.split("/")

    # Fast return when no '.' or '..' components in the path.
    if "." not in components and ".." not in components:
        return path

    # https://datatracker.ietf.org/doc/html/rfc3986#section-5.2.4
    output: list[str] = []
    for component in components:
        if component == ".":
            pass
        elif component == "..":
            if output and output != [""]:
                output.pop()
        else:
            output.append(component)
    return "/".join(output)

def percent_encoded(string: str, safe: str) -> str:
    """
    Use percent-encoding to quote a string.
    """
    NON_ESCAPED_CHARS = UNRESERVED_CHARACTERS + safe

    # Fast path for strings that don't need escaping.
    if not string.rstrip(NON_ESCAPED_CHARS):
        return string

    return "".join(
        [char if char in NON_ESCAPED_CHARS else PERCENT(char) for char in string]
    )

@property
def userinfo(self) -> bytes:
    """
    The URL userinfo as a raw bytestring.
    For example: b"jo%40email.com:a%20secret".
    """
    return self._uri_reference.userinfo.encode("ascii")

@property
def username(self) -> str:
    """
    The URL username as a string, with URL decoding applied.
    For example: "jo@email.com"
    """
    userinfo = self._uri_reference.userinfo
    return unquote(userinfo.partition(":")[0])

@property
def password(self) -> str:
    """
    The URL password as a string, with URL decoding applied.
    For example: "a secret"
    """
    userinfo = self._uri_reference.userinfo
    return unquote(userinfo.partition(":")[2])

@property
def path(self) -> str:
    """
    The URL path as a string. Excluding the query string, and URL decoded.

    For example:

    url = httpx.URL("https://example.com/pa%20th")
    assert url.path == "/pa th"
    """
    path = self._uri_reference.path or "/"
    return unquote(path)

@property
def params(self) -> "QueryParams":
    """
    The URL query parameters, neatly parsed and packaged into an immutable
    multidict representation.
    """
    return QueryParams(self._uri_reference.query)

@property
def fragment(self) -> str:
    """
    The URL fragments, as used in HTML anchors.
    As a string, without the leading '#'.
    """
    return unquote(self._uri_reference.fragment or "")

def copy_merge_params(
    self,
    params: "QueryParams" | dict[str, str | list[str]] | list[tuple[str, str]] | None,
) -> "URL":
    return self.copy_with(params=self.params.copy_update(params))

class QueryParams(typing.Mapping[str, str]):
    """
    URL query parameters, as a multi-dict.
    """

    def __init__(
        self,
        params: (
            "QueryParams" | dict[str, str | list[str]] | list[tuple[str, str]] | str | None
        ) = None,
    ) -> None:
        d: dict[str, list[str]] = {}

        if params is None:
            d = {}
        elif isinstance(params, str):
            d = urldecode(params)
        elif isinstance(params, QueryParams):
            d = params.multi_dict()
        elif isinstance(params, dict):
            # Convert dict inputs like:
            #    {"a": "123", "b": ["456", "789"]}
            # To dict inputs where values are always lists, like:
            #    {"a": ["123"], "b": ["456", "789"]}
            d = {k: [v] if isinstance(v, str) else list(v) for k, v in params.items()}
        else:
            # Convert list inputs like:
            #     [("a", "123"), ("a", "456"), ("b", "789")]
            # To a dict representation, like:
            #     {"a": ["123", "456"], "b": ["789"]}
            for k, v in params:
                d.setdefault(k, []).append(v)

        self._dict = d

    def keys(self) -> typing.KeysView[str]:
        """
        Return all the keys in the query params.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert list(q.keys()) == ["a", "b"]
        """
        return self._dict.keys()

    def values(self) -> typing.ValuesView[str]:
        """
        Return all the values in the query params. If a key occurs more than once
        only the first item for that key is returned.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert list(q.values()) == ["123", "789"]
        """
        return {k: v[0] for k, v in self._dict.items()}.values()

    def items(self) -> typing.ItemsView[str, str]:
        """
        Return all items in the query params. If a key occurs more than once
        only the first item for that key is returned.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert list(q.items()) == [("a", "123"), ("b", "789")]
        """
        return {k: v[0] for k, v in self._dict.items()}.items()

    def multi_items(self) -> list[tuple[str, str]]:
        """
        Return all items in the query params. Allow duplicate keys to occur.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert list(q.multi_items()) == [("a", "123"), ("a", "456"), ("b", "789")]
        """
        multi_items: list[tuple[str, str]] = []
        for k, v in self._dict.items():
            multi_items.extend([(k, i) for i in v])
        return multi_items

    def multi_dict(self) -> dict[str, list[str]]:
        return {k: list(v) for k, v in self._dict.items()}

    def get(self, key: str, default: typing.Any = None) -> typing.Any:
        """
        Get a value from the query param for a given key. If the key occurs
        more than once, then only the first value is returned.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert q.get("a") == "123"
        """
        if key in self._dict:
            return self._dict[key][0]
        return default

    def get_list(self, key: str) -> list[str]:
        """
        Get all values from the query param for a given key.

        Usage:

        q = httpx.QueryParams("a=123&a=456&b=789")
        assert q.get_list("a") == ["123", "456"]
        """
        return list(self._dict.get(key, []))

    def copy_set(self, key: str, value: str) -> "QueryParams":
        """
        Return a new QueryParams instance, setting the value of a key.

        Usage:

        q = httpx.QueryParams("a=123")
        q = q.set("a", "456")
        assert q == httpx.QueryParams("a=456")
        """
        q = QueryParams()
        q._dict = dict(self._dict)
        q._dict[key] = [value]
        return q

    def copy_append(self, key: str, value: str) -> "QueryParams":
        """
        Return a new QueryParams instance, setting or appending the value of a key.

        Usage:

        q = httpx.QueryParams("a=123")
        q = q.append("a", "456")
        assert q == httpx.QueryParams("a=123&a=456")
        """
        q = QueryParams()
        q._dict = dict(self._dict)
        q._dict[key] = q.get_list(key) + [value]
        return q

    def copy_remove(self, key: str) -> QueryParams:
        """
        Return a new QueryParams instance, removing the value of a key.

        Usage:

        q = httpx.QueryParams("a=123")
        q = q.remove("a")
        assert q == httpx.QueryParams("")
        """
        q = QueryParams()
        q._dict = dict(self._dict)
        q._dict.pop(str(key), None)
        return q

    def copy_update(
        self,
        params: (
            "QueryParams" | dict[str, str | list[str]] | list[tuple[str, str]] | None
        ) = None,
    ) -> "QueryParams":
        """
        Return a new QueryParams instance, updated with.

        Usage:

        q = httpx.QueryParams("a=123")
        q = q.copy_update({"b": "456"})
        assert q == httpx.QueryParams("a=123&b=456")

        q = httpx.QueryParams("a=123")
        q = q.copy_update({"a": "456", "b": "789"})
        assert q == httpx.QueryParams("a=456&b=789")
        """
        q = QueryParams(params)
        q._dict = {**self._dict, **q._dict}
        return q

    def __getitem__(self, key: str) -> str:
        return self._dict[key][0]

    def __contains__(self, key: typing.Any) -> bool:
        return key in self._dict

    def __iter__(self) -> typing.Iterator[str]:
        return iter(self.keys())

    def __len__(self) -> int:
        return len(self._dict)

    def __bool__(self) -> bool:
        return bool(self._dict)

    def __hash__(self) -> int:
        return hash(str(self))

    def __eq__(self, other: typing.Any) -> bool:
        if not isinstance(other, self.__class__):
            return False
        return sorted(self.multi_items()) == sorted(other.multi_items())

    def __str__(self) -> str:
        return urlencode(self.multi_dict())

    def __repr__(self) -> str:
        return f"<QueryParams {str(self)!r}>"

def __init__(
    self,
    params: (
        "QueryParams" | dict[str, str | list[str]] | list[tuple[str, str]] | str | None
    ) = None,
) -> None:
    d: dict[str, list[str]] = {}

    if params is None:
        d = {}
    elif isinstance(params, str):
        d = urldecode(params)
    elif isinstance(params, QueryParams):
        d = params.multi_dict()
    elif isinstance(params, dict):
        # Convert dict inputs like:
        #    {"a": "123", "b": ["456", "789"]}
        # To dict inputs where values are always lists, like:
        #    {"a": ["123"], "b": ["456", "789"]}
        d = {k: [v] if isinstance(v, str) else list(v) for k, v in params.items()}
    else:
        # Convert list inputs like:
        #     [("a", "123"), ("a", "456"), ("b", "789")]
        # To a dict representation, like:
        #     {"a": ["123", "456"], "b": ["789"]}
        for k, v in params:
            d.setdefault(k, []).append(v)

    self._dict = d

def __eq__(self, other: typing.Any) -> bool:
    if not isinstance(other, self.__class__):
        return False
    return sorted(self.multi_items()) == sorted(other.multi_items())

